/**
 * Shim for `@deepseek-ai/schemastery`.
 *
 * The real seam only uses it to declare `static Config = z.object({...})`. The
 * plugin under test never reads that declaration, and this test constructs
 * `WebRuntime` directly rather than through a config-validating loader, so the
 * object builder only has to exist and not throw.
 */
function builder() {
  const schema = {}
  schema.default = () => schema
  schema.optional = () => schema
  schema.description = () => schema
  return schema
}

const z = {
  object: () => builder(),
  string: () => builder(),
  number: () => builder(),
  boolean: () => builder(),
  any: () => builder(),
}

export default z
export { z }
